items.command:
/bin/bash -lc "python3 -c 'import json
from pathlib import Path
data = json.loads(Path(\"sales-input.json\").read_text(encoding=\"utf-8\"))
def ints(x):
    if isinstance(x, bool):
        return
    if isinstance(x, int):
        yield x
    elif isinstance(x, list):
        for v in x:
            yield from ints(v)
    elif isinstance(x, dict):
        for v in x.values():
            yield from ints(v)
vals = list(ints(data))
result = {\"total\": sum(vals), \"max\": max(vals)}
Path(\"analysis.json\").write_text(json.dumps(result, ensure_ascii=False, separators=(\",\", \":\")), encoding=\"utf-8\")
print(result)'"

